from pybricks.hubs import PrimeHub
from pybricks.parameters import Direction, Port, Stop
from pybricks.pupdevices import ColorSensor, Motor
from pybricks.robotics import DriveBase

# Set up.
prime_hub = PrimeHub()
Left = Motor(Port.E, Direction.CLOCKWISE)
Right = Motor(Port.A, Direction.COUNTERCLOCKWISE)
drive_base = DriveBase(Right, Left, 56, 4.375 * 25.4)
Flipper = Motor(Port.D, Direction.COUNTERCLOCKWISE)
color_sensor = ColorSensor(Port.C)


# The main program starts here.
print('FUNGUS')
drive_base.use_gyro(True)
prime_hub.imu.reset_heading(0)
drive_base.settings(straight_speed=400)
Flipper.run_angle(500, 95 * 4)
drive_base.straight(-850, then=Stop.BRAKE)
Flipper.control.limits(acceleration=5000)
Flipper.run_angle(500, -95 * 4)
Flipper.control.limits(acceleration=2000)
drive_base.straight(55)
drive_base.turn(87, absolute=True)
drive_base.straight(360)
drive_base.turn(-45)
drive_base.settings(straight_speed=130)
drive_base.straight(-400)
drive_base.settings(straight_speed=400)
drive_base.straight(100)
Flipper.run_angle(500, 400)
drive_base.turn(110)
drive_base.straight(-240)
drive_base.straight(100)
drive_base.turn(-20)
drive_base.settings(straight_speed=600)
drive_base.straight(-1000)
